(1, 1, 1, 'LEAVE_STATUS_NOTIFICATION', 'LEAVE STATUS NOTIFICATION', '<h1>Leave Application Notification</h1>\r\n\r\n<h3>Details:</h3>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td data-row="1">Employee :</td>\r\n			<td data-row="1">{{employee_name}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="2">Leave Type :</td>\r\n			<td data-row="2">{{leave_type}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="3">From Date :</td>\r\n			<td data-row="3">{{from_date}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="4">To Date :</td>\r\n			<td data-row="4">{{to_date}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="5">Leave Status :</td>\r\n			<td data-row="5">{{status}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="5">Leave Reason :</td>\r\n			<td data-row="5">{{reason}}</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br />\r\nThanks', '2020-10-28 08:55:04', '2020-10-30 11:05:59', 0),
(2, 1, 1, 'LEAVE_APPROVAL_NOTIFICATION', 'LEAVE APPROVAL NOTIFICATION', '<h1>Leave Application Notification</h1>\r\n\r\n<h3>Details:</h3>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td data-row="1">Employee :</td>\r\n			<td data-row="1">{{employee_name}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="2">Leave Type :</td>\r\n			<td data-row="2">{{leave_type}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="3">From Date :</td>\r\n			<td data-row="3">{{from_date}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="4">To Date :</td>\r\n			<td data-row="4">{{to_date}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="5">Leave Status :</td>\r\n			<td data-row="5">{{status}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td data-row="5">Leave Reason :</td>\r\n			<td data-row="5">{{reason}}</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br />\r\nThanks', '2020-10-28 09:19:08', '2020-10-30 11:05:36', 0);
